char_data_end:

char_data_size = char_data_end - char_data

; Loads char_data into VRAM as the sprite character table (OBSEL Base=0).
; Call during forced blank. Assumes/leaves A8 XY16 (see init.asm).
load_char_gfx:
	lda #$80            ; increment VRAM address after writing VMDATAH
	sta VMAIN

	setAXY16
	lda #char_vram_addr
	sta VMADDL
	ldx #.loword(char_data)
	stx A1T0L
	ldx #char_data_size
	stx DAS0L

	setA8
	lda #^char_data
	sta A1B0
	lda #$18            ; VMDATAL
	sta BBAD0
	lda #$01            ; mode 1: write 2 bytes (L,H) per src pair, increment src addr
	sta DMAP0
	lda #$01            ; enable DMA channel 0
	sta MDMAEN
	rts

; One (dx, dy, tile) triple per 16x16 OAM sprite needed to cover the whole
; character (3 x 4 = 12 sprites), row-major.
; dx/dy are pixel offsets from the character's top-left corner; tile is the
; first-tile-number to put in OAM (see docs/sprites.md).
char_sprite_info:
	.byte 0, 0, $00
	.byte 16, 0, $02
	.byte 32, 0, $04
	.byte 0, 16, $20
	.byte 16, 16, $22
	.byte 32, 16, $24
	.byte 0, 32, $40
	.byte 16, 32, $42
	.byte 32, 32, $44
	.byte 0, 48, $60
	.byte 16, 48, $62
	.byte 32, 48, $64
char_sprite_info_end:

char_sprite_info_size = char_sprite_info_end - char_sprite_info

; Writes OAM entries for the char_sprite_info grid, placed on screen with
; its top-left corner at (char_x, char_y). Hides all other OAM sprites.
; Call during forced blank. Assumes/leaves A8 XY16 (see init.asm).
char_x = 104
char_y = 80

draw_char_sprites:
	stz OAMADDL
	stz OAMADDH

	ldx #0
sprite_loop:
	lda char_sprite_info,x   ; dx
	clc
	adc #char_x
	sta OAMDATA              ; X position
	lda char_sprite_info+1,x ; dy
	clc
	adc #char_y
	sta OAMDATA              ; Y position
	lda char_sprite_info+2,x ; first tile number
	sta OAMDATA
	lda #$00                 ; palette 0, priority 0, no flip, name table 0
	sta OAMDATA
	inx
	inx
	inx
	cpx #char_sprite_info_size
	bne sprite_loop

	ldx #(12 * 4)
hide_loop:
	lda #$00
	sta OAMDATA              ; X position
	lda #$f0
	sta OAMDATA              ; Y position = 240, off the bottom edge
	lda #$00
	sta OAMDATA              ; tile
	sta OAMDATA              ; attr
	inx
	inx
	inx
	inx
	cpx #(128 * 4)
	bne hide_loop

	stz OAMADDL
	lda #$01
	sta OAMADDH              ; OAM high table starts at byte 512

	ldx #0
zero_high_loop:
	stz OAMDATA
	inx
	cpx #32
	bne zero_high_loop
	rts
